package com.gameaggregator.studioservice.application;
import com.gameaggregator.platform.core.common.exception.NotFoundException; import com.gameaggregator.studioservice.api.StudioDtos.*; import com.gameaggregator.studioservice.domain.*; import com.gameaggregator.studioservice.infrastructure.*; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @Transactional public class StudioService { final StudioRepository studios; final StudioMemberRepository members; final StudioContactRepository contacts; public StudioService(StudioRepository s,StudioMemberRepository m,StudioContactRepository c){studios=s;members=m;contacts=c;} public Studio create(Create r){var s=studios.save(new Studio(r.tenantId(),r.slug(),r.name(),r.ownerUserId()));members.save(StudioMember.owner(s.id,r.ownerUserId()));return s;} public List<Studio> list(){return studios.findAll();} public Studio get(UUID id){return studios.findById(id).orElseThrow(()->new NotFoundException("STUDIO_NOT_FOUND","Studio was not found"));} public Studio update(UUID id,Update r){var s=get(id);s.name=r.name();if(r.settings()!=null)s.settings=r.settings();return s;} public Studio status(UUID id,Status r){var s=get(id);s.status=Studio.Status.valueOf(r.status().toUpperCase(Locale.ROOT));return s;} public void delete(UUID id){studios.delete(get(id));} public StudioMember invite(UUID id,Invite r){get(id);return members.save(StudioMember.invite(id,r.email(),r.role()));} public List<StudioMember> members(UUID id){get(id);return members.findAllByStudioId(id);} public StudioContact contact(UUID id,Contact r){get(id);return contacts.save(new StudioContact(id,r.type(),r.value(),r.primaryContact()));} }
